import worldDots from "./content/world-dots.json";

// ── Dot dataset (generated by scripts/generate-globe-dots.mjs) ──

export const GLOBE_DOTS = worldDots.dots as [number, number][];

// ── Flat equirectangular projection ──
// Latitude is cropped to the inhabited band; Antarctica and the empty
// arctic cap are excluded (matches the generator's crop).

export const LAT_MAX = 84;
export const LAT_MIN = -56;
export const MAP_WIDTH = 1000;
export const MAP_HEIGHT = Math.round((MAP_WIDTH * (LAT_MAX - LAT_MIN)) / 360);

export function projectPoint(lngLat: [number, number]): { x: number; y: number } {
    return {
        x: ((lngLat[0] + 180) / 360) * MAP_WIDTH,
        y: ((LAT_MAX - lngLat[1]) / (LAT_MAX - LAT_MIN)) * MAP_HEIGHT,
    };
}

// ── Country marker coordinates ([lng, lat]) ──
