// Filters a list of ISO country codes down to those that both the backend
// supports and we have coordinates for. This is what keeps unsupported
// countries (e.g. HU, RO) off the map.
export function filterSupportedMarkers(codes: string[]): string[] {
    return codes
        .map((code) => code.toUpperCase())
        .filter((code) => Boolean(COUNTRY_COORDS[code]));
}
